-- V9: Settings -> Configuration seed data (see SETTINGS_CONFIG_API.md section 7)

-- 1. permission levels per role and module (role_permission rows; highest action wins)

-- 2. sections
update config_section set locked = true, system = true where org_id='00000000-0000-0000-0000-000000000001' and area_key='employee_profile' and key in ('basic','work');

-- 3. fields
update config_field f set section_id = s.id, label = 'Mobile', required = true, sort = 10 from config_section s where f.org_id='00000000-0000-0000-0000-000000000001' and f.area_key='employee_profile' and f.key='phone' and s.org_id='00000000-0000-0000-0000-000000000001' and s.area_key='employee_profile' and s.key='personal';
update config_field f set section_id = s.id, required = true, sort = 20 from config_section s where f.org_id='00000000-0000-0000-0000-000000000001' and f.area_key='employee_profile' and f.key='personal_email' and s.org_id='00000000-0000-0000-0000-000000000001' and s.area_key='employee_profile' and s.key='personal';
update config_field set sort = sort + 20 where org_id='00000000-0000-0000-0000-000000000001' and area_key='employee_profile' and key in ('dob','gender','marital','blood','addr','paddr');

-- 4. employee profile: field security (replaces the V7 starter matrix)
delete from config_field_access where field_id in (select id from config_field where org_id='00000000-0000-0000-0000-000000000001' and area_key='employee_profile');
